const catalogue=[['cookware-steel','Stainless steel cookware set','Kitchen','Utensils'],['saucepan','Colour-pop saucepan','Kitchen','Utensils'],['saute-pan','Everyday sauté pan','Kitchen','Utensils'],['casserole','Covered casserole pot','Kitchen','Utensils'],['utensils','Kitchen utensil set','Kitchen','Utensils'],['nesting-bowls','Nesting kitchen bowls','Kitchen','Utensils'],['toaster','Two-slice toaster','Kitchen','Kitchen Appliances'],['dinnerware','Gather-round dinnerware','Dining','Utensils'],['cutlery','Table-ready cutlery set','Dining','Utensils'],['food-carriers','Food carrier set','Storage','Utensils'],['storage-rect','Rectangular food containers','Storage','Utensils'],['storage-square','Square food containers','Storage','Utensils'],['dish-rack','Two-tier dish rack','Cleaning','Home essentials'],['sink-caddy','Sink organiser & soap dispenser','Cleaning','Home essentials'],['microfibre','Microfibre cleaning cloths','Cleaning','Home essentials']];
const products=catalogue.map(([id,name,room,range])=>({id,name,room,range,image:`products/leadsgate-${id}-studio.webp`,cutout:`products/leadsgate-${id}.webp`,home:`products/leadsgate-${id}-home.webp`}));
const $=s=>document.querySelector(s),modal=$('#modal');let room='All',range='All',basket={},savedOnly=false,favourites=[];try{const f=JSON.parse(localStorage.getItem('leadsgate-favourites')||'[]');if(Array.isArray(f))favourites=f.filter(id=>products.some(p=>p.id===id))}catch{}
try{const saved=JSON.parse(localStorage.getItem('leadsgate-list-v2')||'{}');for(const p of products)if(Number.isInteger(saved[p.id])&&saved[p.id]>0)basket[p.id]=Math.min(saved[p.id],99)}catch{}
function show(html){$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal()}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function save(){try{localStorage.setItem('leadsgate-list-v2',JSON.stringify(basket))}catch{}$('#count').textContent=Object.values(basket).reduce((a,b)=>a+b,0);renderBasket()}
function add(id){if(!products.some(p=>p.id===id))return;basket[id]=Math.min((basket[id]||0)+1,99);save();toast('Added to your home list')}
function productCard(p,compact=false){return `<article class="product ${compact?'rail-product':''}"><div class="photo"><button class="view-product" data-view="${p.id}" aria-label="View ${p.name}"><img src="assets/${p.image}" alt="${p.name}" loading="lazy"></button><span>${p.range}</span><button class="favourite ${favourites.includes(p.id)?'is-saved':''}" data-favourite="${p.id}" aria-label="Save ${p.name}" aria-pressed="${favourites.includes(p.id)}">${favourites.includes(p.id)?'♥':'♡'}</button><button class="quick-view" data-view="${p.id}">Quick view</button></div><p class="product-room">${p.room}</p><h3><button class="name-button" data-view="${p.id}">${p.name}</button></h3><div class="product-bottom"><p>Price on enquiry</p><button data-add="${p.id}" class="list-add" aria-label="Add ${p.name}">Add to list ＋</button></div></article>`}
function render(){const query=$('#search').value.trim().toLowerCase();$('#filters').innerHTML=['All','Kitchen','Dining','Cleaning','Storage','Living'].map(r=>`<button class="${r===room?'active':''}" aria-pressed="${r===room}" data-filter="${r}">${r==='All'?'All rooms':r==='Living'?'Living':r}</button>`).join('');let filtered=products.filter(p=>(room==='All'||p.room===room)&&(range==='All'||p.range===range)&&(!savedOnly||favourites.includes(p.id))&&(p.name+' '+p.range+' '+p.room).toLowerCase().includes(query));const sort=$('#sort-products').value;if(sort!=='featured')filtered.sort((a,b)=>sort==='az'?a.name.localeCompare(b.name):b.name.localeCompare(a.name));$('#result-count').textContent=`${filtered.length} ${filtered.length===1?'essential':'essentials'}${range!=='All'?' · '+range:''}${savedOnly?' · Saved favourites':''}`;$('#saved-count').textContent=favourites.length;$('#saved-open').setAttribute('aria-pressed',savedOnly);$('#grid').innerHTML=filtered.map(p=>productCard(p)).join('')||((room==='Living'||range==='Home Decor'||range==='Furniture')?'<div class="empty"><h3>A little more home, coming together.</h3><p>Ask us about Home Decor and Furniture. Product images and specifications are awaiting confirmation.</p><a class="text-link" href="mailto:leadsgateofficial@gmail.com?subject=Home%20decor%20and%20furniture%20enquiry">Enquire about this range ↗</a></div>':`<div class="empty"><h3>${savedOnly?'Your favourites are waiting to be found.':'No essentials found.'}</h3><p>${savedOnly?'Tap a heart on any product to save it here.':'Try another room, range or search term.'}</p><button class="button" id="reset">Show all essentials</button></div>`);document.querySelectorAll('[data-range]').forEach(b=>b.classList.toggle('range-active',b.dataset.range===range&&range!=='All'))}

function detail(id){const p=products.find(p=>p.id===id);if(!p)return;show(`<div class="detail-grid"><div><img id="detail-image" class="detail-photo" src="assets/${p.image}" alt="${p.name}"><div class="image-options" aria-label="Product image views"><button data-image="${p.image}" aria-pressed="true">Studio</button><button data-image="${p.cutout}" aria-pressed="false">Product</button><button data-image="${p.home}" aria-pressed="false">Alternate</button></div></div><div><p class="eyebrow blue">${p.room} · ${p.range}</p><h2>${p.name}</h2><p>Make room for a useful everyday essential. Add this item to your home list and ask LeadsGate for the current price and availability.</p><p class="sample">From the supplied product image pack. Confirm the exact model, material, dimensions, set contents and colour before ordering.</p><button class="button" data-add="${id}">Add to home list ＋</button><p><button class="text-link name-button" id="detail-list">View my home list ↗</button></p></div></div>`)}
function renderBasket(){$('#basket-items').innerHTML=Object.entries(basket).map(([id,n])=>{const p=products.find(p=>p.id===id);return `<div class="basket-row"><img src="assets/${p.cutout}" alt="${p.name}"><div>${p.name}<small>Price on enquiry</small><button data-minus="${id}" aria-label="Reduce ${p.name}">−</button> <span>${n}</span> <button data-add="${id}" aria-label="Increase ${p.name}">+</button><button class="remove" data-remove="${id}">Remove</button></div></div>`}).join('')||'<p>Your home list is waiting. Explore a room to get started.</p>';$('#whatsapp').disabled=!Object.keys(basket).length}
let lastFocus;function openBag(){lastFocus=document.activeElement;if(modal.open)modal.close();$('#drawer').hidden=false;$('#overlay').hidden=false;$('#drawer').setAttribute('role','dialog');$('#drawer').setAttribute('aria-modal','true');document.body.style.overflow='hidden';$('#close-bag').focus()}
function closeBag(){if($('#drawer').hidden)return;$('#drawer').hidden=true;$('#overlay').hidden=true;document.body.style.overflow='';(lastFocus||$('#bag')).focus()}
$('#bag').onclick=openBag;$('#close-bag').onclick=closeBag;$('#overlay').onclick=closeBag;$('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeBag();if(e.key==='Tab'&&!$('#drawer').hidden){const nodes=[...$('#drawer').querySelectorAll('button:not(:disabled),a[href],input,textarea')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const scenes={Kitchen:{image:'kitchen.jpg',title:'Where every good day begins.',items:['cookware-steel','utensils','toaster']},Dining:{image:'dining.jpg',title:'Make room for everyone.',items:['dinnerware','cutlery','food-carriers']},Storage:{image:'home.jpg',title:'Everything in its happy place.',items:['storage-rect','storage-square','nesting-bowls']},Cleaning:{image:'kitchen.jpg',title:'A fresh start, every day.',items:['sink-caddy','dish-rack','microfibre']}};
function scene(name,scroll=false){const s=scenes[name];if(!s)return;room=name;range='All';savedOnly=false;render();const hero=$('.hero');hero.classList.add('scene-changing');const img=$('.hero>img');img.src='assets/'+s.image;img.alt=name+' — lifestyle inspiration';$('.hero-note').innerHTML=`0${Object.keys(scenes).indexOf(name)+1} / ${name}<br><span>${s.title}</span>`;$('.hero-room-nav').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.scene===name);b.setAttribute('aria-pressed',b.dataset.scene===name)});$('.hero-hotspots').innerHTML=s.items.map((id,i)=>`<button class="hotspot hs${i+1}" data-view="${id}" aria-label="Explore ${products.find(p=>p.id===id).name}"><span>＋</span><b>${products.find(p=>p.id===id).name}</b></button>`).join('');$('#room-preview img').src='assets/'+s.image;$('#room-preview h3').textContent=s.title;$('.rooms').querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b.dataset.room===name);b.setAttribute('aria-pressed',b.dataset.room===name)});updateRoomEdit(name);setTimeout(()=>hero.classList.remove('scene-changing'),300);if(scroll)$('#products').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add){add(b.dataset.add);return}if(b.dataset.view)detail(b.dataset.view);if(b.dataset.filter){room=b.dataset.filter;render()}if(b.dataset.scene)scene(b.dataset.scene);if(b.dataset.room)scene(b.dataset.room);if(b.dataset.explore){room=b.dataset.explore;range='All';savedOnly=false;$('#search').value='';render();$('#products').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};if(b.dataset.minus){const id=b.dataset.minus;if(--basket[id]<=0)delete basket[id];save()}if(b.dataset.remove){delete basket[b.dataset.remove];save()}if(b.dataset.image){$('#detail-image').src='assets/'+b.dataset.image;$('.image-options').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b))}if(b.id==='detail-list')openBag();if(b.id==='reset')resetCatalogue()});$('#search').oninput=render;
$('#kit-open').onclick=()=>show(`<p class="eyebrow blue">YOUR HOME KIT</p><h2>Start with what you need.</h2><p>Choose the essentials for your home. We’ll put them in one enquiry.</p><form id="kit-form"><div class="kit-options">${products.map(p=>`<label class="kit-choice"><input type="checkbox" name="kit" value="${p.id}"><img src="assets/${p.cutout}" alt=""><span>${p.name}<small>Price on enquiry</small></span></label>`).join('')}</div><p id="kit-summary">0 items selected · Total: awaiting quote</p><button class="button" type="submit">Add selected items ＋</button></form>`);
modal.addEventListener('change',()=>{if($('#kit-form'))$('#kit-summary').textContent=`${$('#kit-form').querySelectorAll(':checked').length} items selected · Total: awaiting quote`});modal.addEventListener('submit',e=>{if(e.target.id==='kit-form'){e.preventDefault();const ids=[...e.target.querySelectorAll(':checked')].map(x=>x.value);if(!ids.length){toast('Choose at least one essential');return}ids.forEach(id=>basket[id]=Math.min((basket[id]||0)+1,99));save();modal.close();openBag()}});
$('#whatsapp').onclick=()=>{const message='Hello LeadsGate, please confirm prices and availability for my home list:\n\n'+Object.entries(basket).map(([id,n])=>`${n} × ${products.find(p=>p.id===id).name}`).join('\n')+'\n\nPlease confirm the exact product details and delivery or collection options. Thank you.';closeBag();show('<p class="eyebrow blue">YOUR ENQUIRY</p><h2>A little closer to home.</h2><p>Review your list, then open an email draft or copy it. Nothing is sent automatically.</p><textarea id="message" aria-label="Your enquiry message"></textarea><div class="enquiry-actions"><button class="button" id="email-enquiry">Open email draft ↗</button><button class="button light" id="copy">Copy enquiry</button></div>');$('#message').value=message;$('#email-enquiry').onclick=()=>location.href='mailto:leadsgateofficial@gmail.com?subject='+encodeURIComponent('My LeadsGate home list')+'&body='+encodeURIComponent($('#message').value);$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#message').value);toast('Enquiry copied')}catch{$('#message').select();toast('Select and copy your enquiry')}}};
$('#credits').onclick=()=>show(`<p class="eyebrow blue">PHOTOGRAPHY</p><h2>Spaces that inspire.</h2><p>Product images: supplied LeadsGate product pack. Room imagery is illustrative lifestyle inspiration from Pexels and does not show LeadsGate premises or confirmed furniture stock.</p><p><a target="_blank" rel="noopener" href="https://www.pexels.com/photo/interior-of-modern-kitchen-with-dining-table-5825363/">Kitchen · Charlotte May ↗</a></p><p><a target="_blank" rel="noopener" href="https://www.pexels.com/photo/table-with-chairs-in-kitchen-6297088/">Dining · Max Vakhtbovych ↗</a></p><p><a target="_blank" rel="noopener" href="https://www.pexels.com/photo/modern-kitchen-interior-with-furniture-and-dining-zone-6186826/">Home · Max Vakhtbovych ↗</a></p>`);$('#year').textContent=new Date().getFullYear();render();save();

const roomEditorial={Kitchen:{kicker:'01 / The kitchen',description:'For quick breakfasts, slow Sundays and everything in between.',cta:'Explore the kitchen'},Dining:{kicker:'02 / The dining room',description:'Set the table for everyday moments worth sharing.',cta:'Explore dining'},Cleaning:{kicker:'03 / Home care',description:'Little helpers for a home that feels fresh and cared for.',cta:'Explore home care'},Storage:{kicker:'04 / A place for everything',description:'Bring a little order to busy days and everyday essentials.',cta:'Explore storage'}};
function updateRoomEdit(name){const edit=roomEditorial[name];if(!edit)return;$('#room-kicker').textContent=edit.kicker;$('#room-description').textContent=edit.description;$('#room-preview img').alt=name+' lifestyle inspiration';$('#explore-room').dataset.explore=name;$('#explore-room').innerHTML=edit.cta+' <span>↗</span>';$('#room-edit').innerHTML=scenes[name].items.slice(0,3).map(id=>{const p=products.find(p=>p.id===id);return `<button data-view="${id}" aria-label="View ${p.name}"><img src="assets/${p.cutout}" alt=""><span>${p.name}</span></button>`}).join('')}
updateRoomEdit('Kitchen');

function jumpToCatalogue(){$('#products').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function closeCategories(){$('#category-panel').hidden=true;$('#category-toggle').setAttribute('aria-expanded','false')}
function resetCatalogue(){room='All';range='All';savedOnly=false;$('#search').value='';$('#global-search').value='';render()}
function renderFeatured(){const ids=['cookware-steel','dinnerware','storage-rect','toaster','sink-caddy','utensils'];$('#feature-rail').innerHTML=ids.map(id=>productCard(products.find(p=>p.id===id),true)).join('')}
$('#category-toggle').onclick=()=>{const open=$('#category-panel').hidden;$('#category-panel').hidden=!open;$('#category-toggle').setAttribute('aria-expanded',open)};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!e.target.closest('.category-menu'))closeCategories();if(!b)return;if(b.dataset.range){range=b.dataset.range;room='All';savedOnly=false;$('#search').value='';$('#global-search').value='';render();closeCategories();jumpToCatalogue()}if(b.dataset.filterJump){range='All';room=b.dataset.filterJump;savedOnly=false;$('#search').value='';render();closeCategories();jumpToCatalogue()}if(b.dataset.favourite){const id=b.dataset.favourite;if(favourites.includes(id))favourites=favourites.filter(x=>x!==id);else favourites.push(id);try{localStorage.setItem('leadsgate-favourites',JSON.stringify(favourites))}catch{}render();renderFeatured();toast(favourites.includes(id)?'Saved to your favourites':'Removed from favourites')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#category-panel').hidden){closeCategories();$('#category-toggle').focus()}});
$('#header-search').onsubmit=e=>{e.preventDefault();room='All';range='All';savedOnly=false;$('#search').value=$('#global-search').value;render();jumpToCatalogue()};
$('#saved-open').onclick=()=>{$('#global-search').value='';savedOnly=true;range='All';room='All';$('#search').value='';render();jumpToCatalogue()};$('#clear-filters').onclick=resetCatalogue;$('#sort-products').onchange=render;
function scrollRail(direction){$('#feature-rail').scrollBy({left:direction*$('#feature-rail').clientWidth*.8,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}$('#rail-prev').onclick=()=>scrollRail(-1);$('#rail-next').onclick=()=>scrollRail(1);renderFeatured();render();
